async(page)=>{
 const check=(v,m)=>{if(!v)throw Error(m);}, done=()=>page.locator('#maxwell-status').filter({hasText:'Physical-time history complete.'}).waitFor({timeout:30000});
 const upload=async name=>page.locator('#maxwell-file').setInputFiles('/private/tmp/atlas-maxwell-main-atlas-v1/'+name+'.json');
 const save=async name=>{const event=page.waitForEvent('download');await page.locator('#maxwell-export').click();await(await event).saveAs('/private/tmp/atlas-maxwell-main-atlas-v1/'+name+'.json');};
 await done();const baseline=await page.locator('#maxwell-state').textContent();
 await upload('browser-relaxation');await done();check(await page.locator('#maxwell-state').textContent()===baseline,'imported full table');await save('browser-replayed');
 await upload('bad-identity');await page.locator('#maxwell-status').filter({hasText:'Import rejected:'}).waitFor();check(await page.locator('#maxwell-export').isDisabled(),'identity rejection clears export');
 await upload('bad-result');await page.locator('#maxwell-status').filter({hasText:'Run failed:'}).waitFor({timeout:30000});const replayRejection=await page.locator('#maxwell-status').textContent();check(await page.locator('#maxwell-state tr').count()===0,'tampered replay clears all history');
 await page.locator('#maxwell-reset').click();await done();
 await page.locator('#maxwell-parameters').fill('[20000000,12000000,-1]');await page.locator('#maxwell-run').click();await page.locator('#maxwell-status').filter({hasText:'Invalid input:'}).waitFor();check(await page.locator('#maxwell-export').isDisabled(),'invalid input clears export');
 await page.locator('#maxwell-reset').click();await done();check(await page.locator('#maxwell-state').textContent()===baseline,'invalid input recovery');
 await page.locator('#maxwell-parameters').fill('[20000000,12000000,48000000]');await page.locator('#maxwell-run').click();await done();check(await page.locator('#maxwell-state').textContent()!==baseline,'coefficient edit updates response');await save('browser-parameter-edit');
 await page.locator('#maxwell-reset').click();await done();
 if(await page.locator('#maxwell-controls details').getAttribute('open')===null)await page.locator('#maxwell-controls details summary').click();await page.locator('#maxwell-initial').fill('[141000,81000,81000,3000,-2000,1000]');await page.locator('#maxwell-run').click();await done();await save('browser-state-edit');
 await page.locator('#maxwell-reset').click();await done();
 const cancellation=await page.evaluate(()=>{document.querySelector('#maxwell-run').click();const running=document.querySelector('#maxwell-status').textContent;const model=document.querySelector('#model');model.value='hypoplastic-sand-vw96';model.dispatchEvent(new Event('change',{bubbles:true}));return {running,hidden:document.querySelector('#maxwell-laboratory').hidden,status:document.querySelector('#maxwell-status').textContent};});check(cancellation.running.includes('Running'),'actual run starts before switch');check(cancellation.hidden,'switch hides Maxwell');
 await page.locator('#model').selectOption('sls-comsol63-deviatoric-zero-spin-ode');await page.locator('#sls-status').filter({hasText:'complete'}).waitFor({timeout:30000});
 await page.locator('#model').selectOption('maxwell-itasca900-zero-spin-ode');await done();check(await page.locator('#maxwell-state').textContent()===baseline,'switch back runs cleanly');
 await page.goto('http://127.0.0.1:18783/site/index.html#catalogue/maxwell-itasca900-zero-spin-ode');await page.locator('#catalogue-dialog[open]').waitFor();check((await page.locator('#catalogue-detail-status').textContent()).includes('physical-time'),'catalogue profile');check((await page.locator('#catalogue-detail-body').textContent()).includes('zero spin'),'catalogue limitations');const sourceLinks=await page.locator('#catalogue-detail-body a').evaluateAll(a=>a.map(x=>x.href));check(sourceLinks.some(x=>x.includes('modelviscous.html')),'catalogue source hyperlink');await page.locator('#catalogue-explore').click();await done();
 const links=await page.locator('#maxwell-equations a').evaluateAll(a=>a.map(x=>({href:x.href,label:x.textContent})));const local=[];for(const link of links.filter(x=>x.href.startsWith('http://127.0.0.1:18783/'))){const r=await page.request.get(link.href);check(r.ok(),'local source/review/schema link '+link.href);local.push({href:link.href,status:r.status()});}
 check(await page.locator('#maxwell-stress polyline').count()>0,'stress plot geometry');check(await page.locator('#maxwell-strain polyline').count()>0,'strain plot geometry');check(await page.locator('#maxwell-rate polyline').count()>0,'rate plot geometry');
 return {passed:true,import_replay:true,identity_tamper_rejected:true,result_tamper_rejected:replayRejection,invalid_input_recovery:true,parameter_and_initial_state_edits:true,model_switch_cancellation:cancellation,sls_switch:true,catalogue_route_and_sources:true,sourceLinks,localLinks:local,plots:true};
}

